  "Remix creates your own copy of this app. Then change it by chatting — add features, tweak the look, make it fit you. No code needed.": {
    fi: "Remix tekee tästä appista oman kopiosi. Sen jälkeen muutat sitä keskustellen — lisää ominaisuuksia, säädä ilmettä, sovi se itsellesi. Ei koodia tarvita.",
    sv: "Remix skapar en egen kopia av den här appen. Ändra den sedan genom att chatta — lägg till funktioner, justera utseendet, gör den till din. Ingen kod behövs.",
    zh: "Remix 会创建此应用的专属副本。然后通过聊天来修改 — 添加功能、调整外观，让它更适合你。无需代码。",
    es: "Remix crea tu propia copia de esta app. Luego cámbiala chateando — añade funciones, ajusta el aspecto, hazla a tu medida. Sin código.",
    ja: "Remix はこのアプリの自分用コピーを作ります。あとはチャットで変更 — 機能を足したり見た目を整えたり、自分向けにできます。コードは不要です。",
    de: "Remix erstellt eine eigene Kopie dieser App. Ändere sie dann per Chat — füge Funktionen hinzu, passe das Aussehen an, mach sie zu deiner. Kein Code nötig.",
    fr: "Remix crée votre propre copie de cette appli. Modifiez-la ensuite en discutant — ajoutez des fonctions, ajustez l’apparence, adaptez-la à vous. Aucun code nécessaire.",
    hi: "Remix इस ऐप की आपकी अपनी कॉपी बनाता है। फिर चैट करके बदलें — फीचर जोड़ें, लुक ठीक करें, अपने हिसाब से बनाएँ। कोड की ज़रूरत नहीं।",
    ko: "Remix는 이 앱의 내 사본을 만듭니다. 그런 다음 채팅으로 바꾸세요 — 기능을 더하고, 디자인을 다듬고, 나에게 맞게. 코드는 필요 없습니다.",
    it: "Remix crea una tua copia di questa app. Poi modificala chattando — aggiungi funzioni, ritocca l’aspetto, adattala a te. Nessun codice necessario.",
    pt: "O Remix cria uma cópia tua desta app. Depois altera-a conversando — adiciona funções, ajusta o aspeto, adapta-a a ti. Sem código.",
    nl: "Remix maakt een eigen kopie van deze app. Pas hem daarna aan via chat — voeg functies toe, verfijn de look, maak hem van jou. Geen code nodig."
  },
