    ja: "プロンプトでアプリを自分用のバージョンにアレンジできます。",
    de: "Andere können deine App mit einem Prompt in ihre eigene Version verwandeln.",
    fr: "Les gens peuvent adapter votre appli à leur version avec un prompt.",
    hi: "लोग प्रॉम्प्ट से आपके ऐप को अपने संस्करण में ढाल सकते हैं।",
    ko: "프롬프트로 앱을 자신만의 버전으로 바꿀 수 있습니다.",
