  "Hey — I'm Abblet.\n\nI'll build an app from what you describe. For a good first version, tell me what it should do and how you'll use it — the clearer you are, the better the result.\n\nWhat should we make?": {
    fi: "Hei — olen Abblet.\n\nRakennan appin siitä mitä kuvailet. Hyvän ensimmäisen version saat, kun kerrot mitä appin pitäisi tehdä ja miten käytät sitä — mitä selkeämmin, sen parempi tulos.\n\nMitä tehdään?",
    sv: "Hej — jag är Abblet.\n\nJag bygger en app utifrån det du beskriver. För en bra första version, berätta vad den ska göra och hur du ska använda den — ju tydligare, desto bättre resultat.\n\nVad ska vi göra?",
    zh: "你好 — 我是 Abblet。\n\n我会根据你的描述构建应用。要做出好的第一版，请告诉我它该做什么、你要怎么用 — 说得越清楚，效果越好。\n\n我们做什么？",
    es: "Hola — soy Abblet.\n\nCrearé una app a partir de lo que describas. Para una buena primera versión, dime qué debe hacer y cómo la usarás — cuanto más claro, mejor el resultado.\n\n¿Qué hacemos?",
    ja: "やあ — 私は Abblet です。\n\nあなたの説明からアプリを作ります。良い初版のために、何をするアプリか、どう使うかを教えてください — 具体的なほど、良い結果になります。\n\n何を作りましょうか？",
    de: "Hey — ich bin Abblet.\n\nIch baue eine App aus dem, was du beschreibst. Für eine gute erste Version sag mir, was sie tun soll und wie du sie nutzt — je klarer, desto besser das Ergebnis.\n\nWas sollen wir machen?",
    fr: "Salut — je suis Abblet.\n\nJe crée une appli à partir de ce que tu décris. Pour une bonne première version, dis-moi ce qu'elle doit faire et comment tu l'utiliseras — plus c'est clair, meilleur sera le résultat.\n\nOn fait quoi ?",
    hi: "हैलो — मैं Abblet हूँ।\n\nआप जो बताएंगे उससे मैं ऐप बनाऊँगा। अच्छे पहले संस्करण के लिए बताएं कि ऐप क्या करे और आप इसे कैसे इस्तेमाल करेंगे — जितना साफ़, उतना बेहतर नतीजा।\n\nक्या बनाएँ?",
    ko: "안녕하세요 — 저는 Abblet입니다.\n\n말씀하신 내용으로 앱을 만들어 드릴게요. 좋은 첫 버전을 위해 무엇을 하고 어떻게 쓸지 알려 주세요 — 구체적일수록 결과가 좋아집니다.\n\n무엇을 만들까요?",
    it: "Ciao — sono Abblet.\n\nCreerò un'app da quello che descrivi. Per una buona prima versione, dimmi cosa deve fare e come la userai — più sei chiaro, migliore sarà il risultato.\n\nCosa facciamo?",
    pt: "Olá — sou o Abblet.\n\nVou criar uma app a partir do que descreves. Para uma boa primeira versão, diz-me o que deve fazer e como a vais usar — quanto mais claro, melhor o resultado.\n\nO que vamos fazer?",
    nl: "Hoi — ik ben Abblet.\n\nIk bouw een app van wat je beschrijft. Voor een goede eerste versie, vertel wat hij moet doen en hoe je hem gebruikt — hoe duidelijker, hoe beter het resultaat.\n\nWat gaan we maken?"
  },
