    es: "Remixear y usar apps de AI consume crédito. Free se recarga cada mes; Premium añade más — y el crédito no usado se acumula.",
    ja: "リミックスと AIアプリの利用にはクレジットを使います。Free は毎月補充、Premium は上乗せ — 未使用分は繰り越し。",
    de: "Remixen und AI-Apps nutzen verbraucht Guthaben. Free wird monatlich aufgefüllt; Premium legt mehr drauf — ungenutztes Guthaben sammelt sich.",
    fr: "Remixer et utiliser des applis AI consomme du crédit. Free se recharge chaque mois ; Premium en ajoute plus — et le crédit inutilisé s’accumule.",
    hi: "Remix और AI ऐप इस्तेमाल करने से क्रेडिट खर्च होता है। Free हर महीने रिचार्ज होता है; Premium और जोड़ता है — बचा क्रेडिट जमा होता है।",
    ko: "리믹스와 AI 앱 사용은 크레딧을 소모합니다. Free는 매월 충전되고, Premium은 더 추가합니다 — 미사용 크레딧은 누적됩니다.",
