  "Abblet lets you apply your ideas as small personal apps. Describe what you need and Abblet builds a working app that runs in your browser and keeps your data on your device.": {
    fi: "Abbletlla toteutat ideasi pieninä henkilökohtaisina appeina. Kuvaile mitä tarvitset — Abblet rakentaa toimivan appin selaimeesi, data pysyy laitteellasi.",
    sv: "Med Abblet förverkligar du dina idéer som små personliga appar. Beskriv vad du behöver — Abblet bygger en fungerande app som körs i webbläsaren och håller datan på din enhet.",
    zh: "Abblet 把你的想法变成小型个人应用。描述你的需求，Abblet 就会做出可在浏览器运行的应用，数据留在你的设备上。",
    es: "Abblet te permite hacer realidad tus ideas como pequeñas apps personales. Describe lo que necesitas y Abblet crea una app que funciona en el navegador y guarda los datos en tu dispositivo.",
    ja: "Abblet なら、アイデアを小さな個人アプリとして実現できます。必要なものを伝えると、ブラウザで動き、データは端末に残るアプリを作ります。",
    de: "Mit Abblet setzt du Ideen als kleine persönliche Apps um. Beschreibe, was du brauchst — Abblet baut eine funktionierende App, die im Browser läuft und Daten auf deinem Gerät behält.",
    fr: "Abblet te permet de concrétiser tes idées en petites applis personnelles. Décris ce dont tu as besoin : Abblet crée une appli qui tourne dans le navigateur et garde tes données sur l’appareil.",
    hi: "Abblet से आप अपने आइडिया छोटे निजी ऐप के रूप में साकार करते हैं। ज़रूरत बताएं — Abblet एक काम करने वाला ऐप बनाता है जो ब्राउज़र में चलता है और डेटा आपके डिवाइस पर रहता है।",
    ko: "Abblet으로 아이디어를 작은 개인 앱으로 실현하세요. 필요한 것을 설명하면, 브라우저에서 실행되고 데이터는 기기에 남는 앱을 만듭니다.",
    it: "Con Abblet realizzi le tue idee come piccole app personali. Descrivi cosa ti serve: Abblet crea un’app che gira nel browser e tiene i dati sul tuo dispositivo.",
    pt: "Com o Abblet concretizas as tuas ideias em pequenas apps pessoais. Descreve o que precisas — o Abblet cria uma app que corre no navegador e mantém os dados no teu dispositivo.",
    nl: "Met Abblet realiseer je je ideeën als kleine persoonlijke apps. Beschrijf wat je nodig hebt — Abblet bouwt een werkende app die in de browser draait en data op je apparaat houdt."
  },
