  "Anything small and personal: trackers, journals, calculators, checklists, simple games, or quick one-off tools that make your life easier.": {
    fi: "Mitä tahansa pientä ja henkilökohtaista: seurantoja, päiväkirjoja, laskureita, tarkistuslistoja, yksinkertaisia pelejä tai kertakäyttöisiä työkaluja.",
    sv: "Allt som är litet och personligt: trackers, dagböcker, kalkylatorer, checklistor, enkla spel eller snabba engångsverktyg som gör livet enklare.",
    zh: "任何小型个人工具：追踪器、日记、计算器、清单、简单游戏，或让生活更轻松的一次性小工具。",
    es: "Cualquier cosa pequeña y personal: rastreadores, diarios, calculadoras, listas, juegos simples o herramientas puntuales que te facilitan la vida.",
    ja: "小さく個人的なものなら何でも：トラッカー、日記、電卓、チェックリスト、簡単なゲーム、暮らしを楽にするちょっとした道具。",
    de: "Alles Kleine und Persönliche: Tracker, Tagebücher, Rechner, Checklisten, einfache Spiele oder schnelle Einmal-Tools, die den Alltag erleichtern.",
    fr: "Tout ce qui est petit et personnel : suiveurs, journaux, calculateurs, listes, jeux simples ou outils ponctuels qui simplifient la vie.",
    hi: "कुछ भी छोटा और निजी: ट्रैकर, जर्नल, कैलकुलेटर, चेकलिस्ट, सरल गेम, या ज़िंदगी आसान बनाने वाले तुरंत टूल।",
    ko: "작고 개인적인 것이라면 무엇이든: 트래커, 일기, 계산기, 체크리스트, 간단한 게임, 일상을 돕는 일회용 도구.",
    it: "Qualsiasi cosa piccola e personale: tracker, diari, calcolatori, checklist, giochi semplici o strumenti una tantum che ti semplificano la vita.",
    pt: "Tudo o que for pequeno e pessoal: trackers, diários, calculadoras, listas, jogos simples ou ferramentas pontuais que te facilitam a vida.",
    nl: "Alles kleins en persoonlijks: trackers, dagboeken, rekenmachines, checklists, eenvoudige spellen of snelle eenmalige tools die het leven makkelijker maken."
  },
